#include "mmay/bytecode/program.h"

#include <limits.h>
#include <string.h>

#include "mmay/base/hash.h"
#include "bytecode_internal.h"
#include "program_internal.h"


enum {
    MMAY_BYTECODE_PROGRAM_MAGIC_LENGTH = 8,
    MMAY_BYTECODE_PROGRAM_DIGEST_LENGTH = 32
};

static const unsigned char mmay_bytecode_program_magic[
    MMAY_BYTECODE_PROGRAM_MAGIC_LENGTH
] = { 'R', 'U', 'D', 'A', 'B', 'C', 'P', 0 };

typedef struct MarimayBytecodeProgramBuffer {
    MarimayVector bytes;
    size_t limit;
    bool limit_reached;
} MarimayBytecodeProgramBuffer;

typedef struct MarimayBytecodeProgramCursor {
    const unsigned char *bytes;
    size_t length;
    size_t offset;
} MarimayBytecodeProgramCursor;

static int mmay_bytecode_program_compare_symbols(
    MarimaySymbolId left,
    MarimaySymbolId right
) {
    return memcmp(left.bytes, right.bytes, sizeof(left.bytes));
}

static bool mmay_bytecode_program_size_to_u64(size_t value, uint64_t *result) {
    uint64_t converted = (uint64_t)value;
    if (result == NULL || (size_t)converted != value) {
        return false;
    }
    *result = converted;
    return true;
}

static bool mmay_bytecode_program_u64_to_size(uint64_t value, size_t *result) {
    size_t converted = (size_t)value;
    if (result == NULL || (uint64_t)converted != value) {
        return false;
    }
    *result = converted;
    return true;
}

static bool mmay_bytecode_program_add_bounded(
    size_t *total,
    size_t amount,
    size_t limit
) {
    size_t next = 0;
    if (total == NULL || !mmay_size_add(*total, amount, &next) || next > limit) {
        return false;
    }
    *total = next;
    return true;
}

static bool mmay_bytecode_program_consume_work(
    size_t *work,
    size_t amount,
    size_t limit
) {
    return mmay_bytecode_program_add_bounded(work, amount, limit);
}

static bool mmay_bytecode_program_buffer_init(
    MarimayBytecodeProgramBuffer *buffer,
    MarimayAllocator allocator,
    size_t limit
) {
    if (buffer == NULL) {
        return false;
    }
    memset(buffer, 0, sizeof(*buffer));
    buffer->limit = limit;
    return mmay_vector_init(&buffer->bytes, allocator, sizeof(unsigned char));
}

static void mmay_bytecode_program_buffer_dispose(
    MarimayBytecodeProgramBuffer *buffer
) {
    if (buffer != NULL) {
        mmay_vector_dispose(&buffer->bytes);
        memset(buffer, 0, sizeof(*buffer));
    }
}

static bool mmay_bytecode_program_buffer_append(
    MarimayBytecodeProgramBuffer *buffer,
    const void *bytes,
    size_t length
) {
    size_t next = 0;
    if (buffer == NULL || (bytes == NULL && length != 0)
        || !mmay_size_add(buffer->bytes.length, length, &next)) {
        return false;
    }
    if (next > buffer->limit) {
        buffer->limit_reached = true;
        return false;
    }
    return mmay_vector_append(&buffer->bytes, bytes, length);
}

static bool mmay_bytecode_program_buffer_u64(
    MarimayBytecodeProgramBuffer *buffer,
    uint64_t value
) {
    unsigned char encoded[10];
    size_t count = 0;
    do {
        unsigned char byte = (unsigned char)(value & UINT64_C(0x7f));
        value >>= 7;
        if (value != 0) {
            byte = (unsigned char)(byte | 0x80U);
        }
        encoded[count] = byte;
        count += 1;
    } while (value != 0);
    return mmay_bytecode_program_buffer_append(buffer, encoded, count);
}

static MarimayBytecodeCodecStatus mmay_bytecode_program_decode_u64(
    MarimayBytecodeProgramCursor *cursor,
    uint64_t *result
) {
    uint64_t value = 0;
    size_t index = 0;
    if (cursor == NULL || result == NULL) {
        return MMAY_BYTECODE_CODEC_INVALID_ARGUMENT;
    }
    for (index = 0; index < 10; index += 1) {
        unsigned char byte = 0;
        uint64_t payload = 0;
        if (cursor->offset >= cursor->length) {
            return MMAY_BYTECODE_CODEC_TRUNCATED;
        }
        byte = cursor->bytes[cursor->offset];
        cursor->offset += 1;
        payload = (uint64_t)(byte & 0x7fU);
        if (index == 9 && payload > 1) {
            return MMAY_BYTECODE_CODEC_INVALID_ENCODING;
        }
        value |= payload << (index * 7);
        if ((byte & 0x80U) == 0) {
            if (index != 0 && payload == 0) {
                return MMAY_BYTECODE_CODEC_INVALID_ENCODING;
            }
            *result = value;
            return MMAY_BYTECODE_CODEC_OK;
        }
    }
    return MMAY_BYTECODE_CODEC_INVALID_ENCODING;
}

static MarimayBytecodeCodecStatus mmay_bytecode_program_codec_from_verify(
    MarimayBytecodeProgramVerifyStatus status
) {
    if (status == MMAY_BYTECODE_PROGRAM_VERIFY_OK) {
        return MMAY_BYTECODE_CODEC_OK;
    }
    if (status == MMAY_BYTECODE_PROGRAM_VERIFY_ALLOCATION_FAILED) {
        return MMAY_BYTECODE_CODEC_ALLOCATION_FAILED;
    }
    if (status == MMAY_BYTECODE_PROGRAM_VERIFY_LIMIT_REACHED) {
        return MMAY_BYTECODE_CODEC_LIMIT_REACHED;
    }
    return MMAY_BYTECODE_CODEC_VERIFY_FAILED;
}

MarimayBytecodeProgramOptions mmay_bytecode_program_default_options(void) {
    MarimayBytecodeProgramOptions options;
    options.max_functions = 100000;
    options.max_total_registers = 1000000;
    options.max_total_blocks = 1000000;
    options.max_total_instructions = 10000000;
    options.max_total_calls = 1000000;
    options.max_total_call_arguments = 10000000;
    options.max_total_string_constants = 1000000;
    options.max_total_string_bytes = 256U * 1024U * 1024U;
    options.max_total_array_constructions = 1000000;
    options.max_total_array_arguments = 10000000;
    options.max_total_record_layouts = 1000000;
    options.max_total_record_fields = 10000000;
    options.max_total_record_constructions = 1000000;
    options.max_total_record_arguments = 10000000;
    options.max_total_enum_layouts = 1000000;
    options.max_total_enum_variants = 10000000;
    options.max_total_enum_payloads = 10000000;
    options.max_total_enum_constructions = 1000000;
    options.max_total_enum_arguments = 10000000;
    options.max_total_collection_layouts = 1000000;
    options.max_total_interface_layouts = 1000000;
    options.max_total_interface_constructions = 1000000;
    options.max_total_interface_methods = 10000000;
    options.max_encoded_bytes = 256U * 1024U * 1024U;
    options.max_verify_work = 64000000;
    options.function_options = mmay_bytecode_function_default_options();
    return options;
}

bool mmay_bytecode_program_init(
    MarimayBytecodeProgram *program,
    MarimayAllocator allocator,
    size_t source_count,
    MarimayBytecodeProgramOptions options
) {
    if (program == NULL || allocator.allocate == NULL || allocator.resize == NULL
        || allocator.deallocate == NULL || source_count == 0
        || source_count > options.function_options.max_source_files
        || !mmay_bytecode_program_valid_options(options)) {
        return false;
    }
    memset(program, 0, sizeof(*program));
    if (!mmay_vector_init(
            &program->functions,
            allocator,
            sizeof(MarimayBytecodeProgramFunction)
        )) {
        return false;
    }
    program->allocator = allocator;
    program->source_count = source_count;
    program->entry_function = UINT32_MAX;
    program->options = options;
    program->initialized = true;
    return true;
}

void mmay_bytecode_program_dispose(MarimayBytecodeProgram *program) {
    size_t index = 0;
    if (program == NULL) {
        return;
    }
    for (index = 0; index < program->functions.length; index += 1) {
        MarimayBytecodeProgramFunction *function = mmay_vector_at(
            &program->functions,
            index
        );
        if (function != NULL) {
            mmay_bytecode_function_dispose(&function->body);
        }
    }
    mmay_vector_dispose(&program->functions);
    memset(program, 0, sizeof(*program));
}

const MarimayBytecodeProgramFunction *mmay_bytecode_program_function(
    const MarimayBytecodeProgram *program,
    size_t index
) {
    return program != NULL && program->initialized
        ? mmay_vector_at_const(&program->functions, index)
        : NULL;
}

const MarimayBytecodeProgramFunction *mmay_bytecode_program_function_by_symbol(
    const MarimayBytecodeProgram *program,
    MarimaySymbolId symbol
) {
    size_t low = 0;
    size_t high = 0;
    if (program == NULL || !program->initialized) {
        return NULL;
    }
    high = program->functions.length;
    while (low < high) {
        size_t middle = low + (high - low) / 2;
        const MarimayBytecodeProgramFunction *candidate =
            mmay_bytecode_program_function(program, middle);
        int comparison = candidate == NULL ? 1
            : mmay_bytecode_program_compare_symbols(candidate->symbol, symbol);
        if (comparison < 0) {
            low = middle + 1;
        } else if (comparison > 0) {
            high = middle;
        } else {
            return candidate;
        }
    }
    return NULL;
}

bool mmay_bytecode_program_take_function(
    MarimayBytecodeProgram *program,
    MarimaySymbolId symbol,
    MarimayBytecodeFunction *function,
    uint32_t *result
) {
    MarimayBytecodeProgramFunction owned;
    const MarimayBytecodeProgramFunction *previous = NULL;
    if (program == NULL || !program->initialized || function == NULL
        || !function->initialized || result == NULL
        || program->functions.length >= program->options.max_functions
        || program->functions.length >= UINT32_MAX) {
        return false;
    }
    previous = program->functions.length == 0 ? NULL
        : mmay_bytecode_program_function(
            program,
            program->functions.length - 1
        );
    if (previous != NULL && mmay_bytecode_program_compare_symbols(
            previous->symbol,
            symbol
        ) >= 0) {
        return false;
    }
    owned.symbol = symbol;
    owned.body = *function;
    if (!mmay_vector_push(&program->functions, &owned)) {
        return false;
    }
    *result = (uint32_t)(program->functions.length - 1);
    memset(function, 0, sizeof(*function));
    return true;
}

bool mmay_bytecode_program_set_entry(
    MarimayBytecodeProgram *program,
    MarimaySymbolId symbol
) {
    const MarimayBytecodeProgramFunction *function =
        mmay_bytecode_program_function_by_symbol(program, symbol);
    if (program == NULL || !program->initialized || function == NULL) {
        return false;
    }
    program->entry_function = (uint32_t)(function - (const MarimayBytecodeProgramFunction *)
        program->functions.data);
    return true;
}

MarimayBytecodeProgramVerifyStatus mmay_bytecode_program_verify(
    const MarimayBytecodeProgram *program
) {
    probe_program_calls += 1;
    MarimayBytecodeProgramTotals totals;
    size_t work = 0;
    size_t index = 0;
    memset(&totals, 0, sizeof(totals));
    if (program == NULL || !program->initialized
        || !mmay_bytecode_program_valid_options(program->options)
        || program->source_count == 0
        || program->source_count > program->options.function_options.max_source_files
        || program->functions.length == 0
        || program->functions.length > program->options.max_functions
        || program->functions.length > UINT32_MAX
        || program->entry_function >= program->functions.length) {
        return MMAY_BYTECODE_PROGRAM_VERIFY_INVALID_ARGUMENT;
    }
    for (index = 0; index < program->functions.length; index += 1) {
        const MarimayBytecodeProgramFunction *function =
            mmay_bytecode_program_function(program, index);
        MarimayBytecodeVerifyStatus function_status;
        size_t function_work = 0;
        size_t remaining_work = 0;
        size_t call_index = 0;
        if (function == NULL || !mmay_bytecode_program_consume_work(
                &work,
                1,
                program->options.max_verify_work
            )) {
            return function == NULL ? MMAY_BYTECODE_PROGRAM_VERIFY_INVALID_FUNCTION
                : MMAY_BYTECODE_PROGRAM_VERIFY_LIMIT_REACHED;
        }
        if (index != 0) {
            const MarimayBytecodeProgramFunction *previous =
                mmay_bytecode_program_function(program, index - 1);
            if (previous == NULL) {
                return MMAY_BYTECODE_PROGRAM_VERIFY_INVALID_FUNCTION;
            }
            if (mmay_bytecode_program_compare_symbols(
                    previous->symbol,
                    function->symbol
                ) == 0) {
                return MMAY_BYTECODE_PROGRAM_VERIFY_DUPLICATE_SYMBOL;
            }
            if (mmay_bytecode_program_compare_symbols(
                    previous->symbol,
                    function->symbol
                ) > 0) {
                return MMAY_BYTECODE_PROGRAM_VERIFY_INVALID_ARGUMENT;
            }
        }
        if (function->body.source_count != program->source_count
            || !mmay_bytecode_program_function_options_within(
                function->body.options,
                program->options.function_options
            )
            || !mmay_bytecode_program_accumulate_function(
                &totals,
                &function->body,
                program->options
            ) || !mmay_bytecode_program_consume_work(
                &work,
                function->body.register_types.length,
                program->options.max_verify_work
            ) || !mmay_bytecode_program_consume_work(
                &work,
                function->body.blocks.length,
                program->options.max_verify_work
            ) || !mmay_bytecode_program_consume_work(
                &work,
                function->body.instruction_count,
                program->options.max_verify_work
            ) || !mmay_bytecode_program_consume_work(
                &work,
                function->body.call_arguments.length,
                program->options.max_verify_work
            ) || !mmay_bytecode_program_consume_work(
                &work,
                function->body.array_arguments.length,
                program->options.max_verify_work
            ) || !mmay_bytecode_program_consume_nominal_work(
                &function->body,
                &work,
                program->options.max_verify_work
            )) {
            return function->body.source_count != program->source_count
                    || !mmay_bytecode_program_function_options_within(
                        function->body.options,
                        program->options.function_options
                    )
                ? MMAY_BYTECODE_PROGRAM_VERIFY_INVALID_FUNCTION
                : MMAY_BYTECODE_PROGRAM_VERIFY_LIMIT_REACHED;
        }
        remaining_work = program->options.max_verify_work - work;
        function_status = mmay_bytecode_verify_with_work_limit(
            &function->body,
            remaining_work,
            &function_work
        );
        if (function_status == MMAY_BYTECODE_VERIFY_ALLOCATION_FAILED) {
            return MMAY_BYTECODE_PROGRAM_VERIFY_ALLOCATION_FAILED;
        }
        if (function_status == MMAY_BYTECODE_VERIFY_LIMIT_REACHED) {
            return MMAY_BYTECODE_PROGRAM_VERIFY_LIMIT_REACHED;
        }
        if (function_status != MMAY_BYTECODE_VERIFY_OK) {
            return MMAY_BYTECODE_PROGRAM_VERIFY_INVALID_FUNCTION;
        }
        if (!mmay_bytecode_program_consume_work(
                &work,
                function_work,
                program->options.max_verify_work
            )) {
            return MMAY_BYTECODE_PROGRAM_VERIFY_LIMIT_REACHED;
        }
        for (call_index = 0; call_index < function->body.calls.length;
            call_index += 1) {
            const MarimayBytecodeCall *call = mmay_bytecode_call(
                &function->body,
                (MarimayBytecodeCallId)call_index
            );
            const MarimayBytecodeProgramFunction *callee = NULL;
            size_t argument_index = 0;
            if (call == NULL || !mmay_bytecode_program_consume_work(
                    &work,
                    1,
                    program->options.max_verify_work
                )) {
                return call == NULL
                    ? MMAY_BYTECODE_PROGRAM_VERIFY_INVALID_FUNCTION
                    : MMAY_BYTECODE_PROGRAM_VERIFY_LIMIT_REACHED;
            }
            if (call->interface_slot != UINT32_MAX) {
                MarimayBytecodeProgramVerifyStatus interface_status =
                    mmay_bytecode_program_verify_interface_call(
                        program,
                        function,
                        call,
                        &work
                    );
                if (interface_status != MMAY_BYTECODE_PROGRAM_VERIFY_OK) {
                    return interface_status;
                }
                continue;
            }
            callee = mmay_bytecode_program_function_by_symbol(
                program,
                call->callee
            );
            if (callee == NULL) {
                return MMAY_BYTECODE_PROGRAM_VERIFY_UNKNOWN_CALLEE;
            }
            if (!mmay_bytecode_program_same_type(
                    &function->body,
                    call->result_type,
                    call->result_layout,
                    &callee->body,
                    callee->body.result_type,
                    callee->body.result_layout
                )
                || call->argument_count != callee->body.parameter_count) {
                return MMAY_BYTECODE_PROGRAM_VERIFY_SIGNATURE_MISMATCH;
            }
            for (argument_index = 0;
                argument_index < call->argument_count;
                argument_index += 1) {
                const MarimayBytecodeCallArgument *argument =
                    mmay_bytecode_call_argument(
                        &function->body,
                        call->argument_start + argument_index
                    );
                const MarimayBytecodeType *parameter = mmay_vector_at_const(
                    &callee->body.register_types,
                    argument_index
                );
                if (!mmay_bytecode_program_consume_work(
                        &work,
                        1,
                        program->options.max_verify_work
                    )) {
                    return MMAY_BYTECODE_PROGRAM_VERIFY_LIMIT_REACHED;
                }
                if (argument == NULL || parameter == NULL
                    || !mmay_bytecode_program_same_type(
                        &function->body,
                        argument->type,
                        argument->layout,
                        &callee->body,
                        *parameter,
                        mmay_bytecode_register_layout(
                            &callee->body,
                            (uint32_t)argument_index
                        )
                    )) {
                    return MMAY_BYTECODE_PROGRAM_VERIFY_SIGNATURE_MISMATCH;
                }
            }
        }
    }
    return mmay_bytecode_program_verify_nominal_schemas(program, &work);
}

static MarimayBytecodeCodecStatus probe_encode_program(
    const MarimayBytecodeProgram *program,
    MarimayAllocator allocator,
    MarimayOwnedBytes *output
) {
    MarimayBytecodeProgramBuffer payload;
    MarimayBytecodeProgramBuffer envelope;
    MarimayBytecodeProgramVerifyStatus verify_status;
    MarimayBytecodeCodecStatus status = MMAY_BYTECODE_CODEC_OK;
    unsigned char digest[MMAY_BYTECODE_PROGRAM_DIGEST_LENGTH];
    size_t index = 0;
    uint64_t value = 0;
    if (output == NULL) {
        return MMAY_BYTECODE_CODEC_INVALID_ARGUMENT;
    }
    memset(output, 0, sizeof(*output));
    if (program == NULL || !program->initialized || allocator.allocate == NULL
        || allocator.resize == NULL || allocator.deallocate == NULL) {
        return MMAY_BYTECODE_CODEC_INVALID_ARGUMENT;
    }
    verify_status = mmay_bytecode_program_verify(program);
    status = mmay_bytecode_program_codec_from_verify(verify_status);
    if (status != MMAY_BYTECODE_CODEC_OK) {
        return status;
    }
    memset(&payload, 0, sizeof(payload));
    memset(&envelope, 0, sizeof(envelope));
    if (!mmay_bytecode_program_buffer_init(
            &payload,
            allocator,
            program->options.max_encoded_bytes
        ) || !mmay_bytecode_program_buffer_init(
            &envelope,
            allocator,
            program->options.max_encoded_bytes
        )) {
        mmay_bytecode_program_buffer_dispose(&payload);
        mmay_bytecode_program_buffer_dispose(&envelope);
        return MMAY_BYTECODE_CODEC_ALLOCATION_FAILED;
    }
    if (!mmay_bytecode_program_size_to_u64(program->source_count, &value)
        || !mmay_bytecode_program_buffer_u64(&payload, value)
        || !mmay_bytecode_program_size_to_u64(program->functions.length, &value)
        || !mmay_bytecode_program_buffer_u64(&payload, value)
        || !mmay_bytecode_program_buffer_u64(&payload, program->entry_function)) {
        status = payload.limit_reached ? MMAY_BYTECODE_CODEC_LIMIT_REACHED
            : MMAY_BYTECODE_CODEC_ALLOCATION_FAILED;
        goto cleanup;
    }
    for (index = 0; index < program->functions.length; index += 1) {
        const MarimayBytecodeProgramFunction *function =
            mmay_bytecode_program_function(program, index);
        MarimayOwnedBytes encoded;
        memset(&encoded, 0, sizeof(encoded));
        if (function == NULL) {
            status = MMAY_BYTECODE_CODEC_VERIFY_FAILED;
            goto cleanup;
        }
        status = mmay_bytecode_encode_function(&function->body, allocator, &encoded);
        if (status != MMAY_BYTECODE_CODEC_OK) {
            goto cleanup;
        }
        if (!mmay_bytecode_program_size_to_u64(encoded.length, &value)
            || !mmay_bytecode_program_buffer_append(
                &payload,
                function->symbol.bytes,
                sizeof(function->symbol.bytes)
            ) || !mmay_bytecode_program_buffer_u64(&payload, value)
            || !mmay_bytecode_program_buffer_append(
                &payload,
                encoded.data,
                encoded.length
            )) {
            mmay_owned_bytes_dispose(&encoded);
            status = payload.limit_reached ? MMAY_BYTECODE_CODEC_LIMIT_REACHED
                : MMAY_BYTECODE_CODEC_ALLOCATION_FAILED;
            goto cleanup;
        }
        mmay_owned_bytes_dispose(&encoded);
    }
    if (!mmay_sha256(payload.bytes.data, payload.bytes.length, digest)
        || !mmay_bytecode_program_buffer_append(
            &envelope,
            mmay_bytecode_program_magic,
            sizeof(mmay_bytecode_program_magic)
        ) || !mmay_bytecode_program_buffer_u64(
            &envelope,
            MMAY_BYTECODE_PROGRAM_FORMAT_VERSION
        ) || !mmay_bytecode_program_buffer_u64(&envelope, 0)
        || !mmay_bytecode_program_size_to_u64(payload.bytes.length, &value)
        || !mmay_bytecode_program_buffer_u64(&envelope, value)
        || !mmay_bytecode_program_buffer_append(
            &envelope,
            payload.bytes.data,
            payload.bytes.length
        ) || !mmay_bytecode_program_buffer_append(
            &envelope,
            digest,
            sizeof(digest)
        )) {
        status = envelope.limit_reached ? MMAY_BYTECODE_CODEC_LIMIT_REACHED
            : MMAY_BYTECODE_CODEC_ALLOCATION_FAILED;
        goto cleanup;
    }
    if (!mmay_owned_bytes_copy(
            output,
            allocator,
            envelope.bytes.data,
            envelope.bytes.length
        )) {
        status = MMAY_BYTECODE_CODEC_ALLOCATION_FAILED;
    }

cleanup:
    mmay_bytecode_program_buffer_dispose(&payload);
    mmay_bytecode_program_buffer_dispose(&envelope);
    if (status != MMAY_BYTECODE_CODEC_OK) {
        mmay_owned_bytes_dispose(output);
    }
    return status;
}

MarimayBytecodeCodecStatus mmay_bytecode_decode_program(
    const unsigned char *bytes,
    size_t length,
    MarimayAllocator allocator,
    MarimayBytecodeProgramOptions options,
    MarimayBytecodeProgram *output
) {
    MarimayBytecodeProgramCursor envelope;
    MarimayBytecodeProgramCursor payload;
    MarimayBytecodeProgram program;
    MarimayBytecodeCodecStatus status = MMAY_BYTECODE_CODEC_OK;
    unsigned char digest[MMAY_BYTECODE_PROGRAM_DIGEST_LENGTH];
    uint64_t value = 0;
    size_t payload_length = 0;
    size_t payload_end = 0;
    size_t envelope_end = 0;
    size_t index = 0;
    MarimayBytecodeProgramTotals totals;
    if (output == NULL) {
        return MMAY_BYTECODE_CODEC_INVALID_ARGUMENT;
    }
    memset(output, 0, sizeof(*output));
    memset(&program, 0, sizeof(program));
    memset(&totals, 0, sizeof(totals));
    if (bytes == NULL || allocator.allocate == NULL || allocator.resize == NULL
        || allocator.deallocate == NULL || !mmay_bytecode_program_valid_options(options)) {
        return MMAY_BYTECODE_CODEC_INVALID_ARGUMENT;
    }
    if (length > options.max_encoded_bytes) {
        return MMAY_BYTECODE_CODEC_LIMIT_REACHED;
    }
    if (length < MMAY_BYTECODE_PROGRAM_MAGIC_LENGTH) {
        return MMAY_BYTECODE_CODEC_TRUNCATED;
    }
    if (memcmp(bytes, mmay_bytecode_program_magic,
            MMAY_BYTECODE_PROGRAM_MAGIC_LENGTH) != 0) {
        return MMAY_BYTECODE_CODEC_INVALID_ENCODING;
    }
    envelope.bytes = bytes;
    envelope.length = length;
    envelope.offset = MMAY_BYTECODE_PROGRAM_MAGIC_LENGTH;
    status = mmay_bytecode_program_decode_u64(&envelope, &value);
    if (status != MMAY_BYTECODE_CODEC_OK) {
        return status;
    }
    if (value != MMAY_BYTECODE_PROGRAM_FORMAT_VERSION) {
        return MMAY_BYTECODE_CODEC_UNSUPPORTED_VERSION;
    }
    status = mmay_bytecode_program_decode_u64(&envelope, &value);
    if (status != MMAY_BYTECODE_CODEC_OK) {
        return status;
    }
    if (value != 0) {
        return MMAY_BYTECODE_CODEC_UNSUPPORTED_VERSION;
    }
    status = mmay_bytecode_program_decode_u64(&envelope, &value);
    if (status != MMAY_BYTECODE_CODEC_OK) {
        return status;
    }
    if (!mmay_bytecode_program_u64_to_size(value, &payload_length)
        || !mmay_size_add(envelope.offset, payload_length, &payload_end)
        || !mmay_size_add(
            payload_end,
            MMAY_BYTECODE_PROGRAM_DIGEST_LENGTH,
            &envelope_end
        )) {
        return MMAY_BYTECODE_CODEC_LIMIT_REACHED;
    }
    if (payload_end > length || envelope_end > length) {
        return MMAY_BYTECODE_CODEC_TRUNCATED;
    }
    if (envelope_end != length) {
        return MMAY_BYTECODE_CODEC_TRAILING_DATA;
    }
    if (!mmay_sha256(bytes + envelope.offset, payload_length, digest)
        || memcmp(digest, bytes + payload_end, sizeof(digest)) != 0) {
        return MMAY_BYTECODE_CODEC_INVALID_ENCODING;
    }
    payload.bytes = bytes + envelope.offset;
    payload.length = payload_length;
    payload.offset = 0;
    status = mmay_bytecode_program_decode_u64(&payload, &value);
    if (status != MMAY_BYTECODE_CODEC_OK) {
        return status;
    }
    {
        size_t source_count = 0;
        size_t function_count = 0;
        if (!mmay_bytecode_program_u64_to_size(value, &source_count)
            || source_count == 0
            || source_count > options.function_options.max_source_files) {
            return MMAY_BYTECODE_CODEC_LIMIT_REACHED;
        }
        status = mmay_bytecode_program_decode_u64(&payload, &value);
        if (status != MMAY_BYTECODE_CODEC_OK) {
            return status;
        }
        if (!mmay_bytecode_program_u64_to_size(value, &function_count)
            || function_count == 0 || function_count > options.max_functions
            || function_count > UINT32_MAX) {
            return MMAY_BYTECODE_CODEC_LIMIT_REACHED;
        }
        status = mmay_bytecode_program_decode_u64(&payload, &value);
        if (status != MMAY_BYTECODE_CODEC_OK) {
            return status;
        }
        if (value > UINT32_MAX) {
            return MMAY_BYTECODE_CODEC_INVALID_ENCODING;
        }
        if (!mmay_bytecode_program_init(&program, allocator, source_count, options)) {
            return MMAY_BYTECODE_CODEC_INVALID_ARGUMENT;
        }
        program.entry_function = (uint32_t)value;
        for (index = 0; index < function_count; index += 1) {
            MarimaySymbolId symbol;
            MarimayBytecodeFunction function;
            size_t function_length = 0;
            uint32_t function_id = 0;
            memset(&function, 0, sizeof(function));
            if (payload.length - payload.offset < sizeof(symbol.bytes)) {
                status = MMAY_BYTECODE_CODEC_TRUNCATED;
                goto cleanup;
            }
            memcpy(symbol.bytes, payload.bytes + payload.offset,
                sizeof(symbol.bytes));
            payload.offset += sizeof(symbol.bytes);
            status = mmay_bytecode_program_decode_u64(&payload, &value);
            if (status != MMAY_BYTECODE_CODEC_OK) {
                goto cleanup;
            }
            if (!mmay_bytecode_program_u64_to_size(value, &function_length)) {
                status = MMAY_BYTECODE_CODEC_LIMIT_REACHED;
                goto cleanup;
            }
            if (function_length > options.function_options.max_encoded_bytes) {
                status = MMAY_BYTECODE_CODEC_LIMIT_REACHED;
                goto cleanup;
            }
            if (function_length > payload.length - payload.offset) {
                status = MMAY_BYTECODE_CODEC_TRUNCATED;
                goto cleanup;
            }
            status = mmay_bytecode_decode_function(
                payload.bytes + payload.offset,
                function_length,
                allocator,
                options.function_options,
                &function
            );
            if (status != MMAY_BYTECODE_CODEC_OK) {
                goto cleanup;
            }
            {
                bool source_mismatch = function.source_count != source_count;
                if (source_mismatch
                    || !mmay_bytecode_program_accumulate_function(
                        &totals,
                        &function,
                        options
                    )) {
                    mmay_bytecode_function_dispose(&function);
                    status = source_mismatch
                        ? MMAY_BYTECODE_CODEC_VERIFY_FAILED
                        : MMAY_BYTECODE_CODEC_LIMIT_REACHED;
                    goto cleanup;
                }
            }
            payload.offset += function_length;
            if (index != 0) {
                const MarimayBytecodeProgramFunction *previous =
                    mmay_bytecode_program_function(&program, index - 1);
                if (previous == NULL
                    || mmay_bytecode_program_compare_symbols(
                        previous->symbol,
                        symbol
                    ) >= 0) {
                    mmay_bytecode_function_dispose(&function);
                    status = MMAY_BYTECODE_CODEC_INVALID_ENCODING;
                    goto cleanup;
                }
            }
            if (!mmay_bytecode_program_take_function(
                    &program,
                    symbol,
                    &function,
                    &function_id
                )) {
                mmay_bytecode_function_dispose(&function);
                status = MMAY_BYTECODE_CODEC_ALLOCATION_FAILED;
                goto cleanup;
            }
        }
    }
    if (payload.offset != payload.length) {
        status = MMAY_BYTECODE_CODEC_TRAILING_DATA;
        goto cleanup;
    }
    status = mmay_bytecode_program_codec_from_verify(
        mmay_bytecode_program_verify(&program)
    );
    if (status != MMAY_BYTECODE_CODEC_OK) {
        goto cleanup;
    }
    *output = program;
    memset(&program, 0, sizeof(program));
    return MMAY_BYTECODE_CODEC_OK;

cleanup:
    mmay_bytecode_program_dispose(&program);
    memset(output, 0, sizeof(*output));
    return status;
}

MarimayBytecodeCodecStatus mmay_bytecode_encode_program(const MarimayBytecodeProgram *program, MarimayAllocator allocator, MarimayOwnedBytes *output) {
    MarimayBytecodeCodecStatus result = probe_encode_program(program, allocator, output);
    if (result == MMAY_BYTECODE_CODEC_OK) {
        probe_encodings += 1;
        if (!mmay_sha256(output->data, output->length, probe_encoded_digest)) return MMAY_BYTECODE_CODEC_INVALID_ARGUMENT;
    }
    return result;
}

probe.h.text:
void probe_dump(void);
extern unsigned long probe_function_calls, probe_program_calls;
extern unsigned char probe_encoded_digest[32];
extern unsigned long probe_encodings;

bytecode_verify.c.text:
#include "mmay/bytecode/bytecode.h"

#include <limits.h>
#include <string.h>

#include "mmay/base/utf8.h"
#include "bytecode_internal.h"
#include "bytecode_verify_assignments.h"
#include "bytecode_verify_order.h"
#include "bytecode_verify_provenance.h"

static bool mmay_bytecode_consume_verify_work(
    size_t *used,
    size_t amount,
    size_t limit
) {
    size_t next = 0;
    if (used == NULL || !mmay_size_add(*used, amount, &next) || next > limit) {
        return false;
    }
    *used = next;
    return true;
}

MarimayBytecodeVerifyStatus mmay_bytecode_verify_with_work_limit(
    const MarimayBytecodeFunction *function,
    size_t available_work,
    size_t *work_used
) {
    probe_function_calls += 1;
    size_t register_count = 0;
    size_t block_count = 0;
    size_t instruction_total = 0;
    size_t edge_count = 0;
    size_t cell_count = 0;
    size_t block_index = 0;
    size_t work = 0;
    size_t *predecessor_counts = NULL;
    size_t *predecessor_offsets = NULL;
    size_t *predecessor_cursors = NULL;
    uint32_t *predecessors = NULL;
    unsigned char *reachable = NULL;
    uint32_t *queue = NULL;
    unsigned char *incoming = NULL;
    unsigned char *outgoing = NULL;
    unsigned char *scratch = NULL;
    MarimayBytecodeProvenanceAnalysis *provenance = NULL;
    size_t predecessor_counts_size = 0;
    size_t predecessor_offsets_size = 0;
    size_t predecessor_cursors_size = 0;
    size_t predecessors_size = 0;
    size_t reachable_size = 0;
    size_t queue_size = 0;
    size_t cells_size = 0;
    size_t scratch_size = 0;
    size_t work_limit = 0;
    bool has_checked_index_operations = false;
    bool has_required_variant_operations = false;
    bool has_defer_operations = false;
    MarimayBytecodeVerifyStatus status = MMAY_BYTECODE_VERIFY_OK;
    if (work_used == NULL) {
        return MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
    }
    *work_used = 0;
    if (function == NULL || !function->initialized
        || !mmay_bytecode_type_is_result(function->result_type)
        || !mmay_bytecode_type_layout_is_valid(
            function,
            function->result_type,
            function->result_layout
        )
        || function->source_count == 0
        || function->source_count > function->options.max_source_files
        || function->parameter_count > function->register_types.length
        || function->register_types.length > function->options.max_registers
        || function->register_types.length > UINT32_MAX
        || function->blocks.length == 0
        || function->blocks.length > function->options.max_blocks
        || function->blocks.length > UINT32_MAX
        || function->instruction_count > function->options.max_instructions
        || function->calls.length > function->options.max_calls
        || function->calls.length > UINT32_MAX
        || function->call_arguments.length
            > function->options.max_call_arguments
        || function->string_constants.length
            > function->options.max_string_constants
        || function->string_constants.length > UINT32_MAX
        || function->string_bytes > function->options.max_string_bytes
        || function->array_constructions.length
            > function->options.max_array_constructions
        || function->array_constructions.length > UINT32_MAX
        || function->array_arguments.length
            > function->options.max_array_arguments
        || function->collection_types.length
            > function->options.max_collection_layouts
        || function->options.max_registers == 0
        || function->options.max_blocks == 0
        || function->options.max_instructions == 0
        || function->options.max_calls == 0
        || function->options.max_call_arguments == 0
        || function->options.max_string_constants == 0
        || function->options.max_string_bytes == 0
        || function->options.max_array_constructions == 0
        || function->options.max_array_arguments == 0
        || function->options.max_collection_layouts == 0
        || function->options.max_source_files == 0
        || function->options.max_encoded_bytes < MMAY_BYTECODE_MAGIC_LENGTH
        || function->options.max_verify_work == 0) {
        return MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
    }
    if (available_work == 0) {
        return MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
    }
    work_limit = available_work < function->options.max_verify_work
        ? available_work
        : function->options.max_verify_work;
    register_count = function->register_types.length;
    block_count = function->blocks.length;
    {
        size_t array_index = 0;
        for (array_index = 0; array_index < function->array_types.length;
            array_index += 1) {
            const MarimayBytecodeArrayType *array_type =
                mmay_bytecode_array_type(function, (uint32_t)array_index);
            if (array_type == NULL
                || !mmay_bytecode_type_layout_is_valid(
                    function,
                    array_type->element_type,
                    array_type->element_layout
                ) || (array_type->element_type == MMAY_BYTECODE_TYPE_ARRAY
                    && array_type->element_layout >= array_index)) {
                return MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
            }
            if (!mmay_bytecode_consume_verify_work(&work, 1, work_limit)) {
                return MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
            }
        }
    }
    {
        size_t collection_index = 0;
        for (collection_index = 0;
            collection_index < function->collection_types.length;
            collection_index += 1) {
            const MarimayBytecodeCollectionType *collection =
                mmay_bytecode_collection_type(
                    function, (uint32_t)collection_index
                );
            if (collection == NULL
                || !mmay_bytecode_type_layout_is_valid(
                    function, collection->key_type, collection->key_layout
                ) || (!collection->is_set
                    && !mmay_bytecode_type_layout_is_valid(
                        function,
                        collection->value_type,
                        collection->value_layout
                    ))) return MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
            if (!mmay_bytecode_consume_verify_work(&work, 1, work_limit)) {
                return MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
            }
        }
    }
    {
        size_t construction_index = 0;
        size_t expected_argument_start = 0;
        for (construction_index = 0;
            construction_index < function->array_constructions.length;
            construction_index += 1) {
            const MarimayBytecodeArrayConstruction *construction =
                mmay_bytecode_array_construction(
                    function,
                    (MarimayBytecodeArrayConstructionId)construction_index
                );
            uint32_t element_layout = MMAY_BYTECODE_NO_LAYOUT;
            MarimayBytecodeType element_type = construction != NULL
                ? mmay_bytecode_function_array_element_type(
                    function,
                    construction->array_type,
                    construction->array_layout,
                    &element_layout
                )
                : MMAY_BYTECODE_TYPE_INVALID;
            size_t argument_end = 0;
            size_t argument_index = 0;
            if (construction == NULL
                || element_type == MMAY_BYTECODE_TYPE_INVALID
                || !mmay_bytecode_type_layout_is_valid(
                    function, construction->array_type,
                    construction->array_layout
                )
                || construction->argument_start != expected_argument_start
                || !mmay_size_add(
                    construction->argument_start,
                    construction->argument_count,
                    &argument_end
                ) || argument_end > function->array_arguments.length) {
                return MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
            }
            if (!mmay_bytecode_consume_verify_work(&work, 1, work_limit)) {
                return MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
            }
            for (argument_index = construction->argument_start;
                argument_index < argument_end; argument_index += 1) {
                const MarimayBytecodeArrayArgument *argument =
                    mmay_bytecode_array_argument(function, argument_index);
                const MarimayBytecodeType *register_type = argument != NULL
                        && argument->register_id < register_count
                    ? mmay_vector_at_const(
                        &function->register_types, argument->register_id
                    )
                    : NULL;
                if (argument == NULL || register_type == NULL
                    || argument->type != element_type
                    || *register_type != element_type
                    || (construction->array_type == MMAY_BYTECODE_TYPE_ARRAY
                        && (argument->layout != element_layout
                            || mmay_bytecode_register_layout(
                                function, argument->register_id
                            ) != element_layout))) {
                    return register_type == NULL
                        ? MMAY_BYTECODE_VERIFY_INVALID_REGISTER
                        : MMAY_BYTECODE_VERIFY_TYPE_MISMATCH;
                }
                if (!mmay_bytecode_consume_verify_work(&work, 1, work_limit)) {
                    return MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
                }
            }
            expected_argument_start = argument_end;
        }
        if (expected_argument_start != function->array_arguments.length) {
            return MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
        }
    }
    {
        size_t verified_string_bytes = 0;
        size_t string_index = 0;
        for (string_index = 0;
            string_index < function->string_constants.length;
            string_index += 1) {
            const MarimayBytecodeStringConstant *constant =
                mmay_bytecode_string_constant(
                    function,
                    (MarimayBytecodeStringId)string_index
                );
            size_t string_work = 0;
            if (constant == NULL || constant->value.data == NULL
                || !mmay_utf8_validate(
                    (const char *)constant->value.data,
                    constant->value.length,
                    NULL
                ) || !mmay_size_add(
                    verified_string_bytes,
                    constant->value.length,
                    &verified_string_bytes
                ) || !mmay_size_add(
                    constant->value.length,
                    1,
                    &string_work
                )) {
                return MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
            }
            if (!mmay_bytecode_consume_verify_work(
                    &work,
                    string_work,
                    work_limit
                )) {
                return MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
            }
        }
        if (verified_string_bytes != function->string_bytes
            || verified_string_bytes > function->options.max_string_bytes) {
            return MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
        }
    }
    {
        size_t nominal_work = 0;
        status = mmay_bytecode_verify_nominal_metadata(
            function,
            work_limit - work,
            &nominal_work
        );
        if (status != MMAY_BYTECODE_VERIFY_OK) {
            return status;
        }
        work += nominal_work;
    }
    for (block_index = 0; block_index < register_count; block_index += 1) {
        const MarimayBytecodeType *type = mmay_vector_at_const(
            &function->register_types,
            block_index
        );
        if (type == NULL || !mmay_bytecode_type_is_local(*type)
            || (block_index < function->parameter_count
                && !mmay_bytecode_type_is_register(*type))) {
            return MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
        }
    }
    {
        size_t call_index = 0;
        size_t expected_argument_start = 0;
        for (call_index = 0; call_index < function->calls.length;
            call_index += 1) {
            const MarimayBytecodeCall *call = mmay_vector_at_const(
                &function->calls,
                call_index
            );
            size_t argument_index = 0;
            size_t argument_end = 0;
            if (call == NULL || !mmay_bytecode_type_is_result(call->result_type)
                || !mmay_bytecode_type_layout_is_valid(
                    function,
                    call->result_type,
                    call->result_layout
                )
                || call->argument_start != expected_argument_start
                || !mmay_size_add(
                    call->argument_start,
                    call->argument_count,
                    &argument_end
                ) || argument_end > function->call_arguments.length) {
                return MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
            }
            if (!mmay_bytecode_consume_verify_work(
                    &work,
                    1,
                    work_limit
                )) {
                return MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
            }
            for (argument_index = call->argument_start;
                argument_index < argument_end;
                argument_index += 1) {
                const MarimayBytecodeCallArgument *argument = mmay_vector_at_const(
                    &function->call_arguments,
                    argument_index
                );
                const MarimayBytecodeType *register_type = argument != NULL
                        && argument->register_id < register_count
                    ? mmay_vector_at_const(
                        &function->register_types,
                        argument->register_id
                    )
                    : NULL;
                if (argument == NULL || register_type == NULL
                    || !mmay_bytecode_type_is_register(argument->type)
                    || *register_type != argument->type
                    || mmay_bytecode_register_layout(
                        function,
                        argument->register_id
                    ) != argument->layout) {
                    return register_type == NULL
                        ? MMAY_BYTECODE_VERIFY_INVALID_REGISTER
                        : MMAY_BYTECODE_VERIFY_TYPE_MISMATCH;
                }
                if (!mmay_bytecode_consume_verify_work(
                        &work,
                        1,
                        work_limit
                    )) {
                    return MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
                }
            }
            expected_argument_start = argument_end;
        }
        if (expected_argument_start != function->call_arguments.length) {
            return MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
        }
    }
    if (!mmay_size_multiply(block_count, sizeof(size_t), &predecessor_counts_size)
        || !mmay_size_add(block_count, 1, &predecessor_offsets_size)
        || !mmay_size_multiply(
            predecessor_offsets_size,
            sizeof(size_t),
            &predecessor_offsets_size
        ) || !mmay_size_multiply(
            block_count,
            sizeof(size_t),
            &predecessor_cursors_size
        ) || !mmay_size_multiply(block_count, sizeof(unsigned char), &reachable_size)
        || !mmay_size_multiply(block_count, sizeof(uint32_t), &queue_size)) {
        return MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
    }
    predecessor_counts = mmay_allocate_array(
        &function->allocator,
        block_count,
        sizeof(size_t)
    );
    if (predecessor_counts == NULL) {
        return MMAY_BYTECODE_VERIFY_ALLOCATION_FAILED;
    }
    memset(predecessor_counts, 0, predecessor_counts_size);
    for (block_index = 0; block_index < block_count; block_index += 1) {
        const MarimayBytecodeBlock *block = mmay_vector_at_const(
            &function->blocks,
            block_index
        );
        size_t instruction_index = 0;
        if (block == NULL || !block->initialized
            || block->instructions.length == 0
            || !mmay_size_add(
                instruction_total,
                block->instructions.length,
                &instruction_total
            ) || instruction_total > function->options.max_instructions) {
            status = MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
            goto cleanup;
        }
        for (instruction_index = 0;
            instruction_index < block->instructions.length;
            instruction_index += 1) {
            const MarimayBytecodeInstruction *instruction = mmay_vector_at_const(
                &block->instructions,
                instruction_index
            );
            const MarimayOpcodeMetadata *metadata = instruction != NULL
                ? mmay_opcode_metadata(instruction->opcode)
                : NULL;
            bool should_terminate = instruction_index + 1
                == block->instructions.length;
            size_t operand_index = 0;
            size_t instruction_work = 1;
            if (metadata == NULL
                || (metadata->flags & MMAY_OPCODE_FLAG_INVALID) != 0) {
                status = MMAY_BYTECODE_VERIFY_INVALID_OPCODE;
                goto cleanup;
            }
            if (instruction->opcode == MMAY_OPCODE_ARRAY_REQUIRE_INDEX
                || instruction->opcode == MMAY_OPCODE_ARRAY_SET
                || instruction->opcode == MMAY_OPCODE_ARRAY_GET_IN_BOUNDS
                || instruction->opcode == MMAY_OPCODE_ARRAY_SET_IN_BOUNDS) {
                has_checked_index_operations = true;
            }
            if (instruction->opcode == MMAY_OPCODE_ENUM_REQUIRE_VARIANT
                || instruction->opcode == MMAY_OPCODE_ENUM_GET_PAYLOAD) {
                has_required_variant_operations = true;
            }
            if (instruction->opcode == MMAY_OPCODE_DEFER_REGISTER
                || instruction->opcode == MMAY_OPCODE_DEFER_CALL) {
                has_defer_operations = true;
            }
            if (((metadata->flags & MMAY_OPCODE_FLAG_TERMINATOR) != 0)
                != should_terminate) {
                status = MMAY_BYTECODE_VERIFY_INVALID_CONTROL_FLOW;
                goto cleanup;
            }
            if (instruction->span.source >= function->source_count
                || instruction->span.end < instruction->span.start) {
                status = MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
                goto cleanup;
            }
            for (operand_index = 0; operand_index < metadata->operand_count;
                operand_index += 1) {
                MarimayBytecodeOperandKind kind = metadata->operands[operand_index];
                if (kind == MMAY_BYTECODE_OPERAND_REGISTER
                    || kind == MMAY_BYTECODE_OPERAND_BLOCK
                    || kind == MMAY_BYTECODE_OPERAND_CALL
                    || kind == MMAY_BYTECODE_OPERAND_STRING
                    || kind == MMAY_BYTECODE_OPERAND_ARRAY_CONSTRUCTION
                    || kind == MMAY_BYTECODE_OPERAND_BOOL) {
                    uint64_t operand = instruction->operands[operand_index]
                        .unsigned_value;
                    if (kind == MMAY_BYTECODE_OPERAND_REGISTER
                        && operand >= register_count) {
                        status = MMAY_BYTECODE_VERIFY_INVALID_REGISTER;
                        goto cleanup;
                    }
                    if (kind == MMAY_BYTECODE_OPERAND_BLOCK
                        && operand >= block_count) {
                        status = MMAY_BYTECODE_VERIFY_INVALID_CONTROL_FLOW;
                        goto cleanup;
                    }
                    if (kind == MMAY_BYTECODE_OPERAND_CALL) {
                        const MarimayBytecodeCall *call = operand
                                < function->calls.length
                            ? mmay_vector_at_const(
                                &function->calls,
                                (size_t)operand
                            )
                            : NULL;
                        if (call == NULL) {
                            status = MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
                            goto cleanup;
                        }
                        if (!mmay_size_add(
                                instruction_work,
                                call->argument_count,
                                &instruction_work
                            )) {
                            status = MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
                            goto cleanup;
                        }
                    }
                    if (kind == MMAY_BYTECODE_OPERAND_STRING
                        && operand >= function->string_constants.length) {
                        status = MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
                        goto cleanup;
                    }
                    if (kind == MMAY_BYTECODE_OPERAND_ARRAY_CONSTRUCTION) {
                        const MarimayBytecodeArrayConstruction *construction =
                            operand < function->array_constructions.length
                            ? mmay_bytecode_array_construction(
                                function,
                                (MarimayBytecodeArrayConstructionId)operand
                            )
                            : NULL;
                        if (construction == NULL) {
                            status = MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
                            goto cleanup;
                        }
                        if (!mmay_size_add(
                                instruction_work,
                                construction->argument_count,
                                &instruction_work
                            )) {
                            status = MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
                            goto cleanup;
                        }
                    }
                    if (kind == MMAY_BYTECODE_OPERAND_BOOL && operand > 1) {
                        status = MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
                        goto cleanup;
                    }
                }
            }
            if (!mmay_bytecode_consume_verify_work(
                    &work,
                    instruction_work,
                    work_limit
                )) {
                status = MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
                goto cleanup;
            }
        }
        {
            const MarimayBytecodeInstruction *terminator =
                mmay_bytecode_block_terminator(block);
            if (terminator->opcode == MMAY_OPCODE_JUMP) {
                size_t target = (size_t)terminator->operands[0].unsigned_value;
                if (!mmay_size_add(predecessor_counts[target], 1,
                        &predecessor_counts[target])
                    || !mmay_size_add(edge_count, 1, &edge_count)) {
                    status = MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
                    goto cleanup;
                }
            } else if (terminator->opcode == MMAY_OPCODE_BRANCH_BOOL) {
                size_t then_block = (size_t)terminator->operands[1].unsigned_value;
                size_t otherwise = (size_t)terminator->operands[2].unsigned_value;
                if (!mmay_size_add(predecessor_counts[then_block], 1,
                        &predecessor_counts[then_block])
                    || !mmay_size_add(predecessor_counts[otherwise], 1,
                        &predecessor_counts[otherwise])
                    || !mmay_size_add(edge_count, 2, &edge_count)) {
                    status = MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
                    goto cleanup;
                }
            }
        }
    }
    if (instruction_total != function->instruction_count) {
        status = MMAY_BYTECODE_VERIFY_INVALID_ARGUMENT;
        goto cleanup;
    }
    if (has_defer_operations) {
        size_t defer_work = 0;
        status = mmay_bytecode_verify_defer_control_flow(
            function, work_limit - work, &defer_work
        );
        if (status != MMAY_BYTECODE_VERIFY_OK) {
            goto cleanup;
        }
        work += defer_work;
    }
    predecessor_offsets = mmay_allocate_array(
        &function->allocator,
        block_count + 1,
        sizeof(size_t)
    );
    predecessor_cursors = mmay_allocate_array(
        &function->allocator,
        block_count,
        sizeof(size_t)
    );
    if (!mmay_size_multiply(
            edge_count == 0 ? 1 : edge_count,
            sizeof(uint32_t),
            &predecessors_size
        )) {
        status = MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
        goto cleanup;
    }
    predecessors = mmay_allocate_array(
        &function->allocator,
        edge_count == 0 ? 1 : edge_count,
        sizeof(uint32_t)
    );
    reachable = mmay_allocate_array(
        &function->allocator,
        block_count,
        sizeof(unsigned char)
    );
    queue = mmay_allocate_array(
        &function->allocator,
        block_count,
        sizeof(uint32_t)
    );
    if (predecessor_offsets == NULL || predecessor_cursors == NULL
        || predecessors == NULL || reachable == NULL || queue == NULL) {
        status = MMAY_BYTECODE_VERIFY_ALLOCATION_FAILED;
        goto cleanup;
    }
    predecessor_offsets[0] = 0;
    for (block_index = 0; block_index < block_count; block_index += 1) {
        if (!mmay_size_add(
                predecessor_offsets[block_index],
                predecessor_counts[block_index],
                &predecessor_offsets[block_index + 1]
            )) {
            status = MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
            goto cleanup;
        }
        predecessor_cursors[block_index] = predecessor_offsets[block_index];
    }
    for (block_index = 0; block_index < block_count; block_index += 1) {
        const MarimayBytecodeBlock *block = mmay_vector_at_const(
            &function->blocks,
            block_index
        );
        const MarimayBytecodeInstruction *terminator =
            mmay_bytecode_block_terminator(block);
        if (terminator->opcode == MMAY_OPCODE_JUMP) {
            size_t target = (size_t)terminator->operands[0].unsigned_value;
            predecessors[predecessor_cursors[target]] = (uint32_t)block_index;
            predecessor_cursors[target] += 1;
        } else if (terminator->opcode == MMAY_OPCODE_BRANCH_BOOL) {
            size_t then_block = (size_t)terminator->operands[1].unsigned_value;
            size_t otherwise = (size_t)terminator->operands[2].unsigned_value;
            predecessors[predecessor_cursors[then_block]] = (uint32_t)block_index;
            predecessor_cursors[then_block] += 1;
            predecessors[predecessor_cursors[otherwise]] = (uint32_t)block_index;
            predecessor_cursors[otherwise] += 1;
        }
    }
    {
        size_t order_work = 0;
        status = mmay_bytecode_verify_order(
            function, reachable, predecessor_cursors, queue,
            work_limit - work, &order_work
        );
        if (status != MMAY_BYTECODE_VERIFY_OK) goto cleanup;
        work += order_work;
    }
    if (!mmay_size_multiply(block_count, register_count, &cell_count)
        || cell_count > work_limit
        || !mmay_size_multiply(
            cell_count == 0 ? 1 : cell_count,
            sizeof(unsigned char),
            &cells_size
        ) || !mmay_size_multiply(
            register_count == 0 ? 1 : register_count,
            sizeof(unsigned char),
            &scratch_size
        )) {
        status = MMAY_BYTECODE_VERIFY_LIMIT_REACHED;
        goto cleanup;
    }
    incoming = mmay_allocate_array(
        &function->allocator,
        cell_count == 0 ? 1 : cell_count,
        sizeof(unsigned char)
    );
    outgoing = mmay_allocate_array(
        &function->allocator,
        cell_count == 0 ? 1 : cell_count,
        sizeof(unsigned char)
    );
    scratch = mmay_allocate_array(
        &function->allocator,
        register_count == 0 ? 1 : register_count,
        sizeof(unsigned char)
    );
    if (incoming == NULL || outgoing == NULL || scratch == NULL) {
        status = MMAY_BYTECODE_VERIFY_ALLOCATION_FAILED;
        goto cleanup;
    }
    {
        size_t assignment_work = 0;
        /* Predecessor construction no longer needs these block-sized cursors. */
        status = mmay_bytecode_verify_assignments(
            function, predecessor_offsets, predecessors, queue,
            incoming, outgoing, scratch, predecessor_cursors,
            work_limit - work, &assignment_work
        );
        if (status != MMAY_BYTECODE_VERIFY_OK) goto cleanup;
        work += assignment_work;
    }
    {
        size_t provenance_work = 0;
        status = mmay_bytecode_provenance_analyze(
            function,
            predecessor_offsets,
            predecessors,
            queue,
            has_checked_index_operations,
            has_required_variant_operations,
            work_limit - work,
            &provenance_work,
            &provenance
        );
        if (status != MMAY_BYTECODE_VERIFY_OK) {
            goto cleanup;
        }
        work += provenance_work;
    }
    for (block_index = 0; block_index < block_count; block_index += 1) {
        const MarimayBytecodeBlock *block = mmay_vector_at_const(
            &function->blocks,
            block_index
        );
        size_t instruction_index = 0;
        if (register_count != 0) {
            memcpy(
                scratch,
                incoming + block_index * register_count,
                register_count
            );
        }
        mmay_bytecode_provenance_begin_block(provenance, block_index);
        for (instruction_index = 0;
            instruction_index + 1 < block->instructions.length;
            instruction_index += 1) {
            const MarimayBytecodeInstruction *instruction = mmay_vector_at_const(
                &block->instructions,
                instruction_index
            );
            status = mmay_bytecode_provenance_validate_instruction(
                provenance,
                instruction
            );
            if (status != MMAY_BYTECODE_VERIFY_OK) {
                goto cleanup;
            }
            status = mmay_bytecode_verify_value_instruction(
                function,
                instruction,
                scratch
            );
            if (status != MMAY_BYTECODE_VERIFY_OK) {
                goto cleanup;
            }
            {
                size_t provenance_work = 0;
                status = mmay_bytecode_provenance_advance_instruction(
                    provenance,
                    instruction,
                    work_limit - work,
                    &provenance_work
                );
                if (status != MMAY_BYTECODE_VERIFY_OK) {
                    goto cleanup;
                }
                work += provenance_work;
            }
        }
        status = mmay_bytecode_verify_terminator(
            function,
            mmay_bytecode_block_terminator(block),
            scratch
        );
        if (status != MMAY_BYTECODE_VERIFY_OK) {
            goto cleanup;
        }
    }
    {
        size_t integer_range_work = 0;
        status = mmay_bytecode_verify_integer_range_proofs(
            function, work_limit - work, &integer_range_work
        );
        if (status != MMAY_BYTECODE_VERIFY_OK) {
            goto cleanup;
        }
        work += integer_range_work;
    }

cleanup:
    mmay_bytecode_provenance_dispose(provenance);
    mmay_deallocate(
        &function->allocator,
        scratch,
        scratch_size
    );
    mmay_deallocate(
        &function->allocator,
        outgoing,
        cells_size
    );
    mmay_deallocate(
        &function->allocator,
        incoming,
        cells_size
    );
    mmay_deallocate(
        &function->allocator,
        queue,
        queue_size
    );
    mmay_deallocate(
        &function->allocator,
        reachable,
        reachable_size
    );
    mmay_deallocate(
        &function->allocator,
        predecessors,
        predecessors_size
    );
    mmay_deallocate(
        &function->allocator,
        predecessor_cursors,
        predecessor_cursors_size
    );
    mmay_deallocate(
        &function->allocator,
        predecessor_offsets,
        predecessor_offsets_size
    );
    mmay_deallocate(
        &function->allocator,
        predecessor_counts,
        predecessor_counts_size
    );
    if (status == MMAY_BYTECODE_VERIFY_OK) {
        *work_used = work;
    }
    return status;
}

MarimayBytecodeVerifyStatus mmay_bytecode_verify(
    const MarimayBytecodeFunction *function
) {
    size_t work_used = 0;
    size_t available_work = function != NULL
        ? function->options.max_verify_work
        : 0;
    return mmay_bytecode_verify_with_work_limit(
        function,
        available_work,
        &work_used
    );
}

