import datetime
import hashlib
import json
from pathlib import Path
import shlex
import subprocess

root = Path.cwd()
base = root / 'build/bytecode-program-preparation'
out = base / 'identity'
out.mkdir(exist_ok=True)
smart = json.loads((base / 'SMART.json').read_text())
frozen = json.loads((base / 'frozen-inputs.json').read_text())
reference_path = root / 'docs/implementation/evidence/cp42-vm-preparation-comprehensive-2026-09-09.json'
reference = json.loads(reference_path.read_text())
bench = root.parent / 'algorithm-benchmarks'
sha = lambda p: hashlib.sha256(Path(p).read_bytes()).hexdigest()

def verify():
    for p, h in frozen.items(): assert sha(root / p) == h, p
    for p, h in reference['metadata']['source_sha256'].items(): assert sha(bench / p) == h, p
verify()
record = {'status': 'running', 'started_utc': datetime.datetime.now(datetime.timezone.utc).isoformat(),
    'note': 'Count and canonical-bytecode identity probe only; no timing evidence. Checks execute normally; wrappers count completed verifier entries and hash successful canonical program encoding.',
    'source_sha256': reference['metadata']['source_sha256'], 'builds': {}, 'workloads': {}}
for label, build in [('before', root / smart['baseline']['on']), ('after', base / 'mmay')]:
    build = build.parent
    target = out / label
    target.mkdir(exist_ok=True)
    (target / 'probe.h').write_text('void probe_dump(void);\nextern unsigned long probe_function_calls, probe_program_calls;\nextern unsigned char probe_encoded_digest[32];\nextern unsigned long probe_encodings;\n')
    (target / 'probe.c').write_text('''#include "probe.h"
#include <stdio.h>
unsigned long probe_function_calls, probe_program_calls, probe_encodings;
unsigned char probe_encoded_digest[32];
void probe_dump(void) {
    fprintf(stderr, "PROOF {\\"function_checks\\":%lu,\\"program_checks\\":%lu,\\"encodings\\":%lu,\\"sha256\\":\\"", probe_function_calls, probe_program_calls, probe_encodings);
    for (unsigned i = 0; i < 32; ++i) fprintf(stderr, "%02x", probe_encoded_digest[i]);
    fputs("\\"}\\n", stderr);
}
''')
    inputs = {}
    for source_path, name in [('bootstrap/main.c','main'),('bootstrap/src/bytecode/bytecode_verify.c','bytecode_verify'),('bootstrap/src/bytecode/program.c','program')]:
        source = subprocess.check_output(['git', 'show', smart['parent_revision'] + ':' + source_path], text=True) if label == 'before' else (root / source_path).read_text()
        inputs[source_path] = hashlib.sha256(source.encode()).hexdigest()
        if name == 'main':
            assert source.count('    return exit_code;') == 1
            source = source.replace('    return exit_code;', '    probe_dump();\n    return exit_code;')
        elif name == 'bytecode_verify':
            marker = '    size_t register_count = 0;'
            assert source.count(marker) == 1
            source = source.replace(marker, '    probe_function_calls += 1;\n' + marker)
        else:
            marker = '    MarimayBytecodeProgramTotals totals;\n    size_t work = 0;'
            assert source.count(marker) == 1
            source = source.replace(marker, '    probe_program_calls += 1;\n' + marker)
            marker = 'MarimayBytecodeCodecStatus mmay_bytecode_encode_program('
            assert source.count(marker) == 1
            source = source.replace(marker, 'static MarimayBytecodeCodecStatus probe_encode_program(')
            source += '''\nMarimayBytecodeCodecStatus mmay_bytecode_encode_program(const MarimayBytecodeProgram *program, MarimayAllocator allocator, MarimayOwnedBytes *output) {
    MarimayBytecodeCodecStatus result = probe_encode_program(program, allocator, output);
    if (result == MMAY_BYTECODE_CODEC_OK) {
        probe_encodings += 1;
        if (!mmay_sha256(output->data, output->length, probe_encoded_digest)) return MMAY_BYTECODE_CODEC_INVALID_ARGUMENT;
    }
    return result;
}\n'''
        (target / (name + '.c')).write_text(source)
    flags = {}
    for line in (build / 'CMakeFiles/mmay_bootstrap.dir/flags.make').read_text().splitlines():
        if ' = ' in line:
            k, v = line.split(' = ',1); flags[k] = shlex.split(v)
    commands, objects = [], []
    for name in ['main', 'bytecode_verify', 'program', 'probe']:
        command = ['/usr/bin/cc'] + flags['C_DEFINES'] + flags['C_INCLUDES'] + flags['C_FLAGS']
        command += ['-I', str(root / 'bootstrap/src/bytecode'), '-I', str(target), '-include', str(target / 'probe.h'), '-c', str(target / (name+'.c')), '-o', str(target / (name+'.o'))]
        commands.append(command); subprocess.run(command, check=True); objects.append(str(target / (name+'.o')))
    command = []
    for word in shlex.split((build / 'CMakeFiles/mmay.dir/link.txt').read_text()):
        if word == 'CMakeFiles/mmay.dir/bootstrap/main.c.o': command += objects
        elif word == 'mmay': command.append(str(target / 'mmay'))
        elif word.endswith('.a'): command.append(str(build / word))
        else: command.append(word)
    commands.append(command); subprocess.run(command, check=True)
    record['builds'][label] = {'original_compiler_sha256': sha(build / 'mmay'), 'instrumented_compiler_sha256': sha(target / 'mmay'), 'archive_sha256': sha(build / 'libmmay_bootstrap.a'), 'inputs_sha256': inputs, 'commands': commands,
        'instrumentation': {p.name: {'sha256': sha(p), 'text': p.read_text()} for p in target.glob('*.[ch]')}}
for name, row in reference['workloads'].items():
    records = {}
    for label in ['before','after']:
        command = list(row['commands']['marimay-vm'])
        source = Path('marimay/benchmarks') / name.replace('-', '_') if row.get('anchor') else Path('marimay/catalog')
        command[0], command[2] = str(out / label / 'mmay'), str(bench / source)
        result = subprocess.run(command, cwd=bench, capture_output=True, text=True, timeout=180)
        assert result.returncode == 0 and result.stdout == row['expected_stdout'], (name,label,result.stdout,result.stderr)
        assert result.stderr.startswith('PROOF ') and len(result.stderr.splitlines()) == 1
        records[label] = {'command': command, 'stdout': result.stdout, 'stderr': result.stderr, 'proof': json.loads(result.stderr[6:])}
    before, after = (records[k]['proof'] for k in ['before','after'])
    assert before['encodings'] == after['encodings'] == 1
    assert before['sha256'] == after['sha256']
    assert before['program_checks'] == 5 and after['program_checks'] == 4
    assert before['function_checks'] % 8 == 0 and before['function_checks'] // 8 * 5 == after['function_checks']
    record['workloads'][name] = records
    (out / 'report.json').write_text(json.dumps(record,indent=2)+'\n')
    print(name, before['function_checks'], '->', after['function_checks'], 'canonical bytecode identical', flush=True)
verify()
record['status'] = 'passed';record['finished_utc'] = datetime.datetime.now(datetime.timezone.utc).isoformat()
(out / 'report.json').write_text(json.dumps(record,indent=2)+'\n')

